async function main(){
  console.log("=== Formcrete Import v2 (Jul 2026) ===\n");

  // 1: Connect
  const {data:ping, error:pErr} = await supabase.from("projects").select("id").limit(1);
  if(pErr){ err("Supabase connect", pErr); return; }
  console.log("✓ Supabase connected");
  let localOk = false;
  try{ await pool.query("SELECT 1"); localOk=true; console.log("✓ Local PG connected\n"); }
  catch(e){ console.warn("⚠ Local PG not available\n"); }

  // 2: Fetch users
  const {data:users} = await supabase.from("users").select("id,name,username,role");
  const byName = {};
  for(const u of (users||[])){
    byName[u.name.toLowerCase()] = u;
    if(u.username) byName[u.username.toLowerCase()] = u;
  }

  // 3: Create missing users
  const SKIP = new Set(["rds","n/a","na","tbd","unknown"]);
  const allNames = new Set();
  for(const r of ALL_ROWS){
    for(const f of [r.detailer, r.checker]){
      if(!f) continue;
      for(const p of f.split(/[\/,&]/)){
        const n = norm(p.trim());
        if(n && n.length > 1 && !SKIP.has(n.toLowerCase())) allNames.add(n);
      }
    }
  }
  console.log("--- Processing " + allNames.size + " names ---");
  for(const name of allNames){
    const key = name.toLowerCase();
    if(byName[key]){ console.log("  ✓ " + name); continue; }
    const uname = name.toLowerCase().replace(/\s+/g,"_").replace(/[^a-z0-9_]/g,"");
    const {data:nu, error:ne} = await supabase.from("users")
      .insert({name, username:uname, password:"Rds@2025", role:"User", client_name:"", email:""})
      .select().single();
    if(ne) err(`create user "${name}"`, ne);
    else{ byName[key]=nu; console.log("  + CREATED: " + name); }
  }

  // 4: Test insert
  console.log("\n--- Test insert ---");
  const {data:tp, error:tpe} = await supabase.from("projects")
    .insert({name:"__FC_TEST__", client:"Formcrete", color:"#6366f1", description:"test", assigned_users:[], deadline:null})
    .select().single();
  if(tpe){ err("Test project", tpe); return; }
  const {data:tt, error:tte} = await supabase.from("tasks")
    .insert({project_id:tp.id, title:"__test__", status:"Not Yet Started", priority:"Medium", assignee:"", client:"Formcrete", tags:[], files:[]})
    .select().single();
  if(tte){ err("Test task", tte); await supabase.from("projects").delete().eq("id",tp.id); return; }
  await supabase.from("tasks").delete().eq("id",tt.id);
  await supabase.from("projects").delete().eq("id",tp.id);
  console.log("✓ Test passed — safe to proceed\n");

  // 5: Delete old Formcrete (Supabase)
  console.log("--- Removing old Formcrete data (Supabase) ---");
  const {data:oldP} = await supabase.from("projects").select("id,name,client");
  const fcOld = (oldP||[]).filter(p=>(p.client||"").toLowerCase().includes("formcrete"));
  console.log("  Found " + fcOld.length + " existing projects");
  for(const p of fcOld){
    await supabase.from("tasks").delete().eq("project_id",p.id);
    await supabase.from("projects").delete().eq("id",p.id);
    console.log("  🗑 " + p.name);
  }

  // 6: Delete old Formcrete (local PG)
  if(localOk){
    try{
      console.log("\n--- Removing old Formcrete data (local PG) ---");
      const {rows:localP} = await pool.query("SELECT id,name FROM projects WHERE LOWER(client) LIKE '%formcrete%'");
      console.log("  Found " + localP.length + " local projects");
      for(const p of localP){
        await pool.query("DELETE FROM tasks WHERE project_id=$1",[p.id]);
        await pool.query("DELETE FROM projects WHERE id=$1",[p.id]);
        console.log("  🗑 " + p.name);
      }
    }catch(e){ console.warn("  ⚠ Local PG delete:", e.message); }
  }

  // 7: Group rows by project
  const byProj = {};
  for(const r of ALL_ROWS){ if(!byProj[r.project]) byProj[r.project]=[]; byProj[r.project].push(r); }
  const projNames = Object.keys(byProj);

  // 8: Insert into Supabase
  console.log("\n--- Inserting " + projNames.length + " projects into Supabase ---");
  let pOk=0, tOk=0, pFail=0, tFail=0;
  const projMap = {};
  for(let ci=0; ci<projNames.length; ci++){
    const pName = projNames[ci];
    const tasks = byProj[pName];
    const color = COLORS[ci % COLORS.length];
    const deadline = tasks.reduce((m,t)=>(!t.due_date?m:(!m||t.due_date>m?t.due_date:m)), null);
    const aSet = new Set();
    for(const t of tasks){
      for(const f of [t.detailer,t.checker]){
        if(!f) continue;
        for(const p of f.split(/[\/,&]/)){
          const u = byName[norm(p.trim()).toLowerCase()];
          if(u?.username) aSet.add(u.username);
        }
      }
    }
    const {data:proj, error:pe} = await supabase.from("projects").insert({
      name:pName, client:"Formcrete", color,
      description:"Formcrete Projects Tracker 2026",
      assigned_users:[...aSet], deadline:deadline||null,
    }).select().single();
    if(pe){ err(`project "${pName}"`, pe); pFail++; continue; }
    pOk++; projMap[pName] = proj.id;
    for(const t of tasks){
      const assignee = norm((t.detailer||t.checker||"").split(/[\/,&]/)[0].trim());
      const {error:te} = await supabase.from("tasks").insert({
        project_id:proj.id, title:t.title, status:safeStatus(t.status),
        priority:"Medium", assignee,
        detailer:normField(t.detailer), checker:normField(t.checker),
        client_sub_date:t.client_sub_date||null, due_date:t.due_date||null,
        client:"Formcrete", tags:[], files:[],
      });
      if(te){ err(`task "${t.title}"`, te); tFail++; }
      else tOk++;
    }
    console.log("  ✓ [" + tasks.length + "] " + pName);
  }
  console.log("\nSupabase: " + pOk + " projects, " + tOk + " tasks | " + (pFail+tFail) + " failed");

  // 9: Insert into local PG
  if(localOk){
    try{
      console.log("\n--- Inserting into local PG ---");
      let lpOk=0, ltOk=0;
      for(let ci=0; ci<projNames.length; ci++){
        const pName = projNames[ci];
        const tasks = byProj[pName];
        const color = COLORS[ci % COLORS.length];
        const deadline = tasks.reduce((m,t)=>(!t.due_date?m:(!m||t.due_date>m?t.due_date:m)), null);
        const aSet = new Set();
        for(const t of tasks){
          for(const f of [t.detailer,t.checker]){
            if(!f) continue;
            for(const p of f.split(/[\/,&]/)){
              const u = byName[norm(p.trim()).toLowerCase()];
              if(u?.username) aSet.add(u.username);
            }
          }
        }
        const {rows:[proj]} = await pool.query(
          `INSERT INTO projects(name,client,color,description,assigned_users,deadline)
           VALUES($1,'Formcrete',$2,'Formcrete Projects Tracker 2026',$3,$4) RETURNING id`,
          [pName, color, JSON.stringify([...aSet]), deadline||null]
        );
        lpOk++;
        for(const t of tasks){
          const assignee = norm((t.detailer||t.checker||"").split(/[\/,&]/)[0].trim());
          await pool.query(
            `INSERT INTO tasks(project_id,title,status,priority,assignee,detailer,checker,client_sub_date,due_date,client,tags,files)
             VALUES($1,$2,$3,'Medium',$4,$5,$6,$7,$8,'Formcrete','[]','[]')`,
            [proj.id, t.title, safeStatus(t.status), assignee, normField(t.detailer), normField(t.checker), t.client_sub_date||null, t.due_date||null]
          );
          ltOk++;
        }
      }
      console.log("Local PG: " + lpOk + " projects, " + ltOk + " tasks");
    }catch(e){ console.warn("  ⚠ Local PG insert error:", e.message); }
  }

  if(localOk) await pool.end();
  console.log("\n=== Done! ===");
}

main().catch(e=>{ console.error("FATAL:", e.message); process.exit(1); });
